interface Harness {
	sent: { content: string; options: Record<string, unknown> | undefined }[];
	state: SessionState;
	scheduler: FakeScheduler;
	ctx: Record<string, unknown>;
	emit(event: string, payload?: unknown): Promise<void>;
	command(args: string): Promise<void>;
}

