let activeHarnesses: Harness[] = [];
const realDateNow = Date.now;
let clock: FakeScheduler;

function makeHarness(options?: { sessionId?: string; kind?: "main" | "sub"; idle?: boolean }): Harness {
	const scheduler = new FakeScheduler();
