		return id;
	}

	clearTimer(id: number): void {
		this.#timers.delete(id);
	}

	advance(ms: number): void {
		const target = this.now + ms;
		for (;;) {
			let nextId: number | undefined;
			let nextDue = Number.POSITIVE_INFINITY;
			for (const [id, timer] of this.#timers) {
