		const h = await boot({ idle: false, kind: "sub", sessionId: "sub-1" });
		await h.startRun();
		await h.command("pause");
		await h.endRun(ABORTED("Deadline exceeded"));
		await h.command("resume");
		h.scheduler.advance(2_000);
		expect(h.sent).toHaveLength(0);
	});

